//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//	NAME:						Rate Of Change
//	CREATOR:					Helgevold - Jan Magne Dybvik
// REQUIREMENTS: 		NX CPU
//
//-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
//  VERSION LOG:
//	 VERSION			DATE				SIGN								DESCRIPTION
//	 1.0.0				2023-11-07			Jan Magne Dybvik		Initial release
//	 2.0.0				2025-03-25		William Veim					Rework
//	 2.0.1				2025-10-16			William Veim					Improved logic
//
//================================================================================================================================
//
//			DESCRTIPTION: 	
//			Calculates change in value over a time periode
//		
//===============================================================================================================================

(*************************************************************************
 *	INITIALIZE AND VARIABLE CONTROL
 *************************************************************************)

IF P_First_Run THEN
	Wrk_ValueLast := Inp_Value;
END_IF;

Wrk_TimeSinceLastSample :=  ADD_TIME(In1:=Wrk_TimeSinceLastSample, In2:=GetMyTaskInterval());
 
 (*************************************************************************
 *	LOGIC AND FUNCTION
 *************************************************************************)
 
IF Wrk_TimeSinceLastSample >= Cfg_SampleInterval THEN

	// Calculate value differance from last call
	IF Inp_Value>Wrk_ValueLast AND Wrk_ValueLast > 0 THEN
		Wrk_ValueChange := HE_ABSValue(((Inp_Value / Wrk_ValueLast) - 1)*100);
	ELSIF Wrk_ValueLast > Inp_Value AND Inp_Value > 0 THEN
		Wrk_ValueChange := HE_ABSValue(((Wrk_ValueLast / Inp_Value) - 1)*100);
	ELSE
		Wrk_ValueChange:=0;
	END_IF;
	
	// Store input value from last call
	Wrk_ValueLast := Inp_Value;

	Wrk_TimeFactor := LINT_TO_REAL(TimeToNanoSec(Wrk_TimeSinceLastSample)/10**9);
	Wrk_RateOfChange := Wrk_ValueChange / Wrk_TimeFactor;

	Wrk_TimeSinceLastSample := T#0s;
	
	IF Wrk_RateOfChange >= Cfg_RateOfChange_Threshold THEN
		Inc(Wrk_FaultCounter);
		Clear(Wrk_OKCounter);
	ELSE
		Inc(Wrk_OKCounter);
	END_IF;
	
END_IF;

IF Wrk_FaultCounter > Cfg_FaultAccumulated_Threshold THEN
	Wrk_AccumulatedFault:=TRUE;
	Clear(Wrk_FaultCounter);
END_IF;

IF Wrk_OKCounter > Cfg_FaultAccumulated_Threshold THEN
	Wrk_AccumulatedFault:=FALSE;
	Clear(Wrk_OKCounter);
END_IF;

 (*************************************************************************
 *	UPDATING OUTPUS
 *************************************************************************)
 
Out_RateOfChange := Wrk_RateOfChange;
Out_FaultAccumulated:=Wrk_AccumulatedFault;
Out_Fault:= Wrk_RateOfChange > Cfg_RateOfChange_Threshold;
